lib_funcs='''
def find_block(grid, color=0):
    """Bounding box (top, left, height, width) of all cells of a color."""
    cells=[(i,j) for i,r in enumerate(grid) for j,v in enumerate(r) if v==color]
    rs=[p[0] for p in cells]; cs=[p[1] for p in cells]
    return min(rs),min(cs),max(rs)-min(rs)+1,max(cs)-min(cs)+1

def find_sprite_bbox(grid, bg, extra_ignore=(0,)):
    """Bounding box of all cells not equal to the background color (or extras)."""
    cols={v for r in grid for v in r}-{bg,*extra_ignore}
    cells=[(i,j) for i,r in enumerate(grid) for j,v in enumerate(r) if v in cols]
    rs=[p[0] for p in cells]; cs=[p[1] for p in cells]
    return min(rs),min(cs),max(rs)-min(rs)+1,max(cs)-min(cs)+1

def bg_color(grid):
    """The most frequent color in the grid."""
    return max({v for r in grid for v in r}, key=lambda c: sum(r.count(c) for r in grid))

def crop(grid, top, left, height, width):
    """The height x width subgrid whose top-left cell is (top, left)."""
    return [row[left:left + width] for row in grid[top:top + height]]

def hmirror(grid):
    """Each row of the grid reversed (mirror left to right)."""
    return [row[::-1] for row in grid]

def paste(grid, block, top, left):
    """Copy block into grid at (top, left), clipped to grid bounds."""
    out=[row[:] for row in grid]
    for i,r in enumerate(block):
        for j,v in enumerate(r):
            if 0<=top+i<len(out) and 0<=left+j<len(out[0]):
                out[top+i][left+j]=v
    return out

def stamp_tiled(grid, block, top, left, height, width):
    """Tile block over a height x width region of grid at (top, left)."""
    out=[row[:] for row in grid]
    for i in range(height):
        for j in range(width):
            out[top+i][left+j]=block[i%len(block)][j%len(block[0])]
    return out
'''
